// Error Handler Lite: one Slack credential, no database.
// The two settings below are the only lines you may want to edit.
const NON_PRODUCTION = /^(TEST|TEMP|DEMO)\b/i;   // workflows whose failures are not posted
const WINDOW_HOURS = { P1: 1, P2: 6 };            // the same failure is posted once per window (24 at most: older records are forgotten)

const d = $json || {};
const exec = d.execution || {};
const err = exec.error || {};
const trig = d.trigger || {};
const terr = trig.error || {};
const wfName = (d.workflow && d.workflow.name) || 'unknown';
const wfId = (d.workflow && d.workflow.id) || '';
const execLine = exec.url ? `Execution: ${exec.url}` : `Execution ID: ${exec.id || 'n/a'} (trigger-stage failure, no URL)`;
try {
  const node = (err.node && err.node.name) || exec.lastNodeExecuted || (terr.node && terr.node.name) || 'trigger';
  // Error text can carry secrets (a URL with a key in it, a token in a header). Mask them
  // before the text is sent anywhere.
  const redact = (t) => String(t)
    .replace(/\b([a-z][a-z0-9+.-]*:\/\/)[^\s\/@:"']+:[^\s\/@"']+@/gi, '$1[redacted]@')
    .replace(/(https?:\/\/[^\s?#"']+)\?[^\s"']*/gi, '$1?[query removed]')
    .replace(/(hooks\.slack\.com\/services\/|api\.telegram\.org\/bot)[^\s"']+/gi, '$1[redacted]')
    .replace(/\b([Bb]earer|[Bb]asic|BEARER|BASIC)\s+(?=[A-Za-z0-9._~+\/=-]*(?:\d|[a-z][A-Z]))[A-Za-z0-9._~+\/=-]{8,}/g, '$1 [redacted]')   // a token, not the word after "basic" in a sentence
    .replace(/([A-Za-z0-9_-]*(?:api[_-]?key|token|secret(?:[_-]?(?:access[_-]?)?key)?|password|passwd|pwd|authorization))(["']?\s*[:=]\s*["']?)(?!bearer\b|basic\b)[^\s"',;&]+/gi, '$1$2[redacted]')
    .replace(/\S+/g, (tok) => /^https?:\/\//i.test(tok) || tok.includes('/') ? tok : tok.replace(/[A-Za-z0-9+_-]{40,}={0,2}/g, '[redacted]'));   // long runs, never inside a link or a file path
  const msg = redact(err.message || terr.message || 'Unknown error').slice(0, 1900);
  const errName = String(err.name || terr.name || '');
  const authFail = /unauthori[sz]ed|authori[sz]ation failed|check your credentials|invalid[_ ]?(token|grant|credential)|token (has )?expired|status code (401|403)\b/i;
  const httpCode = String(err.httpCode || terr.httpCode || '');   // n8n rewrites 401/403 messages, so check the code too

  // Rule table, first match wins.
  let tier = 'P2', reason = 'production failure';
  const inj = msg.match(/FAULT-INJECTOR (P[123])/i);
  // The test override counts only when the failing workflow IS the fault injector. The name
  // comes from n8n, not from the error text, so an error message cannot lower its own tier.
  if (inj && /Fault Injector/i.test(wfName)) { tier = inj[1].toUpperCase(); reason = 'fault injector'; }
  else if (NON_PRODUCTION.test(wfName)) { tier = 'P3'; reason = 'non-production workflow'; }
  else if (authFail.test(msg) || authFail.test(errName) || ['401', '403'].includes(httpCode)) { tier = 'P1'; reason = 'credential or auth failure'; }
  if (tier === 'P3') return [];   // not posted; the failure stays in n8n's execution list

  // Repeat check against the handler's own workflow data (no database). Only a failure that
  // was actually posted is remembered (by the Remember node, after Slack succeeds).
  const msgPrefix = msg.split(/\d{4}-\d{2}-\d{2}T/)[0].slice(0, 80).trim();
  const key = [wfId || wfName, node, tier, msgPrefix].join('|');
  const sent = $getWorkflowStaticData('global').sent || {};
  const hours = WINDOW_HOURS[tier];
  if (sent[key] && Date.now() - sent[key] < hours * 3600 * 1000) return [];   // already posted inside the window

  const emoji = tier === 'P1' ? ':rotating_light:' : ':warning:';
  const slackText = [
    `${emoji} *${tier}* (${reason}): *${wfName}* failed at \`${node}\``,
    `Error: ${msg.slice(0, 500)}`,
    execLine,
    `_The same failure will not be posted again for ${hours} hour${hours === 1 ? '' : 's'}._`
  ].join('\n');
  return [{ json: { key, tier, slackText } }];
} catch (e) {
  // The rule table itself failed: post that, rather than lose the original failure.
  const m = String((e && e.message) || e);
  return [{ json: { key: '', tier: 'P2', slackText: `:warning: *P2* (handler could not classify): *${wfName}* failed. Classifier error: ${m}\n${execLine}` } }];
}

// Runs only after Slack accepted the post, so a failed send is never counted as an alert.
const c = $('Classify').first().json;
if (!c.key) return [{ json: { remembered: false } }];
const store = $getWorkflowStaticData('global');
const sent = store.sent || {};
const now = Date.now();
sent[c.key] = now;
// Keep the store small: forget anything older than a day.
for (const k of Object.keys(sent)) if (now - sent[k] > 24 * 3600 * 1000) delete sent[k];
store.sent = sent;
return [{ json: { remembered: true, key: c.key } }];
